const $=id=>document.getElementById(id), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ico=n=>`<span class="ico" style="--icon:url('assets/${n}.svg')" aria-hidden="true"></span>`;
let lastRenderedPage=-1;
let profiles=[defaultProfile(),{...defaultProfile('Strong Vibration'),StrongScale:109}],index=0,draft=clone(profiles[0]),changed=false,applied=0,signal=50,motorTimer,measuring=false,report='',startup=false,notifications=true,language='English',demoState='Bluetooth',batteryPercent=42,raw=[8,11],axes=[128,128,128,128];
const stateText=()=>demoState==='Disconnected'?'Controller disconnected':demoState==='Driver update required'?'Update the driver to configure this controller':demoState==='Bluetooth unavailable'?'Bluetooth vibration channel unavailable':demoState==='Send failed'?'Last vibration command failed':demoState==='Charging'?'USB · Charging':demoState;
const connected=()=>demoState!=='Disconnected';
function tell(s){$('status').textContent=s}
function dirty(){changed=true;tell('Unsaved changes · '+draft.Name)}
function choose(label,items,value,handler){return `<label class="field-label">${esc(label)}<span class="combo" style="display:flex;margin-top:8px"><select aria-label="${esc(label)}" onchange="${handler}">${items.map(x=>{const[v,n]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(n)}</option>`}).join('')}</select></span></label>`}
function slider(label,key,min,max,value=draft[key],handler=`setField('${key}',+this.value)`){return `<div class="range-row"><label class="range-label" for="r-${key}">${label}<output id="o-${key}">${value}%</output></label><input id="r-${key}" aria-label="${label}" type="range" min="${min}" max="${max}" value="${value}" oninput="$('o-${key}').textContent=this.value+'%';${handler}"></div>`}
function check(label,bit){return `<label><input type="checkbox" ${draft.Flags&bit?'checked':''} onchange="draft.Flags=this.checked?draft.Flags|${bit}:draft.Flags&~${bit};dirty();live()"> ${label}</label>`}
function setField(k,v){draft[k]=v;if(k==='StrongScale'||k==='WeakScale'){profiles[index][k]=v;persist();tell(connected()?'Motor gain saved immediately in preview':'Motor gain saved · waiting for controller')}else dirty();live()}
function modal(title,body,buttons=''){const d=$('dialog');d.innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${body}<p class="error" id="dialog-error" role="alert"></p><div class="actions"><button onclick="$('dialog').close()">Cancel</button>${buttons}</div>`;d.showModal()}
function info(title,text){modal(title,`<p>${esc(text)}</p>`,'<button class="primary" onclick="$(\'dialog\').close()">OK</button>')}
function persist(){try{localStorage.setItem('stadialink-profiles-v3',JSON.stringify(profiles))}catch{}}
function save(){try{validate(draft);if(profiles.some((p,i)=>i!==index&&p.Name.toLowerCase()===draft.Name.toLowerCase()))throw Error('A profile with that name already exists.');profiles[index]=clone(draft);changed=false;persist();if(connected()&&demoState!=='Driver update required'){applied=index;tell('Saved & applied in preview · '+draft.Name)}else tell('Profile saved · apply after connecting a supported controller');show(current)}catch(e){info('Cannot save profile',e.message)}}
function pickProfile(n){if(changed){modal('Discard unsaved changes?',`<p>Switching profiles replaces the current draft.</p>`,`<button class="primary" onclick="$('dialog').close();loadProfile(${n})">Discard & switch</button>`);$('profile').value=index;return}loadProfile(n)}
function loadProfile(n){index=n;draft=clone(profiles[n]);changed=false;show(current);tell('Profile selected · '+draft.Name)}
function selectKey(k){selected=k;show(0);const target=[...document.querySelectorAll('.controller-key')].find(x=>x.dataset.key===k);if(target)target.focus({preventScroll:true})}
function assign(k,v){const focusLabel=document.activeElement?.getAttribute('aria-label');const n=physical.indexOf(selected);draft[k][n]=v;if(k==='Actions'&&v){draft.Map[n]=0;if(v>=13&&!keyOptions.some(x=>x[0]===draft.Keys[n]))draft.Keys[n]=65}dirty();show(0);if(focusLabel){const control=[...document.querySelectorAll('#page select')].find(el=>el.getAttribute('aria-label')===focusLabel);control?.focus({preventScroll:true})}}
function keyControls(n){return choose('Key',keyOptions,draft.Keys[n]||65,`assign('Keys',+this.value)`)+`<div class="checkboxes">${['Ctrl','Alt','Shift','Win'].map((x,j)=>`<label><input type="checkbox" ${draft.Modifiers[n]&(1<<j)?'checked':''} onchange="draft.Modifiers[${n}]=this.checked?draft.Modifiers[${n}]|${1<<j}:draft.Modifiers[${n}]&~${1<<j};dirty()"> ${x}</label>`).join('')}</div>`}
function bar(n,configured=false){return `<div class="meter-label"><span>${n?'Right trigger · R2':'Left trigger · L2'}</span><strong id="value-${n}">0%</strong></div><div class="meter" id="meter-${n}" role="meter" aria-label="${n?'Right trigger':'Left trigger'} ${configured?'configured output':'physical input'}" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"><span id="fill-${n}"></span>${configured?`<i class="deadzone" id="dz-${n}"></i><i class="raw" id="raw-${n}"></i><i class="threshold" id="threshold-${n}"></i>`:''}</div><p class="sub" id="readout-${n}">${configured?'Input 0% · Output 0%':'Raw physical input'}</p>`}
function show(i){if(i!==current){clearTimeout(motorTimer)}const pageChanged=i!==lastRenderedPage;lastRenderedPage=i;current=i;$('heading').textContent=titles[i];$('subtitle').textContent=subs[i];$('nav').innerHTML=titles.map((n,j)=>`<button class="${i===j?'selected':''}" ${i===j?'aria-current="page"':''} title="${n}" onclick="show(${j})">${ico(icons[j])}<span class="nav-label">${n}</span></button>`).join('');$('profile').innerHTML=profiles.map((p,j)=>`<option value="${j}" ${j===index?'selected':''}>${esc(p.Name)}</option>`).join('');
let s='';const n=physical.indexOf(selected),a=draft.Actions[n];
if(i===0)s=`<div class="mapping"><div class="stack"><section class="card"><div class="card-head"><h2>Stadia Controller</h2><span class="connection">${esc(stateText())}</span></div><div class="controller-stage">${controller}</div><p class="controller-note">Select a button on the controller to change its assignment.</p><details style="margin-top:20px"><summary>All 19 inputs</summary><div class="input-chips">${physical.map((x,j)=>`<button aria-pressed="${x===selected}" onclick="selectKey(physical[${j}])">${x}</button>`).join('')}</div></details></section><div class="two">${[0,1].map(j=>`<section class="card meter-card">${bar(j)}</section>`).join('')}</div></div><section class="card inspector"><h2>Button mapping</h2>${choose('Physical input',physical,selected,'selectKey(this.value)')}${choose('Function',actionNames.map((x,j)=>[j,x]),a,"assign('Actions',+this.value)")}${a===0?choose('Gamepad output',destinations,draft.Map[n],"assign('Map',+this.value)"):a>=13?keyControls(n):''}<div class="assignment"><strong>${esc(selected)} → ${esc(a?actionNames[a]:destinations.find(x=>x[0]===draft.Map[n])[1])}</strong><p class="sub">${a?'Keep StadiaLink open for Windows actions.':'Multiple inputs can share an output. Choose Unmapped to disable an input.'}</p>${n>=17?'<p class="sub">Button outputs activate above the shared trigger threshold.</p>':''}</div></section></div>`;
if(i===1)s=`<div class="stack"><div class="two">${['Left','Right'].map((x,j)=>`<section class="card"><h2>${x} stick</h2><svg class="scope" viewBox="0 0 140 140" aria-label="${x} stick input and configured output"><circle cx="70" cy="70" r="64" fill="#202020" stroke="#888"/><path d="M6 70H134M70 6V134" stroke="#555"/><circle id="ring-${j}" cx="70" cy="70" r="0" fill="#ffffff12" stroke="#777" stroke-dasharray="3 3"/><circle id="input-${j}" cx="70" cy="70" r="6" fill="none" stroke="white"/><circle id="output-${j}" cx="70" cy="70" r="4" fill="var(--accent)"/></svg><p class="sub" id="xy-${j}" style="text-align:center">○ Physical input · ● Configured output</p>${slider(x+' deadzone',x+'Deadzone',0,40)}<button onclick="setField('${x}Deadzone',0);show(1)">No deadzone</button>${slider(x+' sensitivity',x+'Sensitivity',50,200)}<div class="checkboxes">${check('Invert horizontal axis',1<<(j*2))}${check('Invert vertical axis',1<<(j*2+1))}</div></section>`).join('')}</div><section class="card"><h2>Triggers</h2><div class="two" style="margin-top:24px">${[0,1].map(j=>`<div>${bar(j,true)}</div>`).join('')}</div><div class="legend"><span>White: physical input</span><span>Accent: configured output</span><span>Amber: button threshold</span></div>${slider('Trigger deadzone','TriggerDeadzone',0,40)}${slider('Remapped button threshold','TriggerThreshold',1,100)}<p class="sub">Threshold applies to button assignments for both triggers.</p><div class="checkboxes">${check('Swap left and right triggers',16)}${check('Swap left and right sticks',32)}</div></section></div>`;
if(i===2)s=`<div class="stack"><div class="banner">Motor gains save immediately. Other profile changes use Save & apply.</div><div class="two">${['Strong','Weak'].map((x,j)=>`<section class="card"><h2>${j?'Right · light':'Left · strong'} motor</h2><p class="sub">${j?'High-frequency':'Low-frequency'} feedback</p>${slider('Game vibration gain',x+'Scale',0,200)}<p id="motor-output-${j}" class="sub"></p><div class="actions"><button onclick="testMotor('${j?'Right':'Left'} motor')">Test ${j?'right':'left'} motor</button></div></section>`).join('')}</div><section class="card"><h2>Test vibration</h2>${slider('Test signal','signal',0,100,signal,'signal=+this.value;live()')}<div class="actions"><button onclick="testMotor('Both motors')">Test both motors</button><button onclick="testMotor('Continuous vibration',true)">Continuous vibration</button><button onclick="stopMotor()">Stop vibration</button></div><p id="motor-status" class="banner" style="margin-top:24px" role="status">Ready · simulated motor tests</p><p class="sub">Gains above 100% require a driver with extended rumble support.</p></section></div>`;
if(i===3)s=`<div class="profiles"><section class="card"><h2>Your profiles</h2><div class="actions"><button onclick="newProfile(false)">+ New profile</button><button onclick="importProfile()">Import JSON</button></div>${profiles.map((p,j)=>`<button class="profile-option ${j===index?'selected':''}" onclick="pickProfile(${j})">${esc(p.Name)}<small>${j===applied?'Applied to demo controller':j===index?'Selected for editing':'Saved profile'}</small></button>`).join('')}</section><section class="card"><h2>Profile details</h2><label class="field-label" for="name" style="margin-top:24px">Name</label><input id="name" class="textbox" maxlength="60" value="${esc(draft.Name)}" oninput="draft.Name=this.value;dirty()"><div class="detail-row"><span>Inputs</span><span>19 assignments</span></div><div class="detail-row"><span>Motor gains</span><span>${draft.StrongScale}% / ${draft.WeakScale}%</span></div><div class="actions"><button onclick="newProfile(true)">Duplicate</button><button onclick="exportProfile()">Export JSON</button><button ${profiles.length<2?'disabled':''} onclick="deleteProfile()">Delete profile</button></div><p class="sub" style="margin-top:20px">Keep at least one profile. Selected and applied profiles can differ.</p></section></div>`;
if(i===4)s=settingsPage();
$('page').innerHTML=(!connected()||demoState==='Driver update required'?`<div class="banner warning">${esc(stateText())}. ${!connected()?'Connect by USB or pair in Windows Bluetooth settings.':'Install the current StadiaLink driver.'} <button onclick="show(4)">Connection help</button></div>`:'')+s;
if(i===0){const svg=document.querySelector('.controller-stage svg');svg.setAttribute('role','group');const hits=[['L2',128,12,19],['R2',427,12,19],['L1',128,36,18],['R1',427,36,18],['Options',216,79,18],['Menu',340,79,18],['Assistant',239,118,17],['Capture',316,118,17],['Stadia',278,197,23],['L3',196,197,34],['R3',359,197,34],['D-pad ↑',127,83,16],['D-pad ↓',127,144,16],['D-pad ←',96,113,16],['D-pad →',158,113,16]];svg.insertAdjacentHTML('beforeend',hits.map(([k,x,y,r])=>`<g class="controller-key hit" data-key="${k}" tabindex="0" role="button" aria-label="Map ${k}"><circle cx="${x}" cy="${y}" r="${r}"/></g>`).join(''));document.querySelectorAll('.controller-key').forEach(k=>{k.classList.toggle('active',k.dataset.key===selected);k.onclick=()=>selectKey(k.dataset.key);k.onkeydown=e=>{if(['Enter',' '].includes(e.key)){e.preventDefault();selectKey(k.dataset.key)}}})}if(pageChanged){document.querySelector('.content').scrollTop=0;document.getElementById('layout').classList.remove('expanded')}live();updateConnectionStatus();}
function settingsPage(){return `<div class="stack"><section class="card"><h2>Appearance</h2><p class="sub">Choose your accent color.</p><div class="swatches">${[['Stadia green','#B5E879'],['Windows blue','#8CC8FF'],['Teal','#76DDCF'],['Lavender','#C6B6FF'],['Rose','#FFB3CA'],['Amber','#F4CA82']].map(([n,c])=>`<button class="swatch" style="--swatch:${c}" aria-label="${n}" title="${n}" aria-pressed="${getComputedStyle(document.documentElement).getPropertyValue('--accent').trim().toUpperCase()===c}" onclick="accent('${c}',this)"></button>`).join('')}</div></section><div class="setting-row"><div><strong>Start with Windows</strong><p>Saves immediately in the installed app.</p></div><input class="toggle" type="checkbox" aria-label="Start with Windows" ${startup?'checked':''} onchange="startup=this.checked;tell('Startup preference simulated')"></div><div class="setting-row"><div><strong>Connection & battery notifications</strong><p>Connection, low battery and charging notices.</p></div><input class="toggle" type="checkbox" aria-label="Connection and battery notifications" ${notifications?'checked':''} onchange="notifications=this.checked;dirty()"></div><div class="setting-row"><div><strong>Language</strong><p>Preview copy remains English.</p></div>${choose('Display language',['English','Español','Deutsch','Français'],language,'language=this.value;dirty()')}</div><section class="card"><h2>Voice & shortcuts</h2><p class="sub">Use the same key combination in your game or Discord.</p><div class="stack" style="margin-top:20px">${[[12,'Push to talk'],[11,'Toggle microphone mute'],[10,'Additional shortcut']].map(([n,t])=>`<button class="shortcut-row" onclick="shortcut(${n})"><strong>${t}</strong><span>${physical[n]} · ${esc(shortcutSummary(n))} ›</span></button>`).join('')}</div></section><section class="card"><h2>Connection</h2><p class="sub">${esc(stateText())}</p><p class="sub">Pair your Stadia controller in Windows Bluetooth settings, or connect with a USB cable.</p><div class="actions"><button onclick="info('Windows Bluetooth settings','The installed app opens Windows Bluetooth settings here. This preview does not change system settings.')">Open Bluetooth settings</button><button onclick="tell('Demo discovery completed · '+stateText())">Detect again</button></div><details style="margin-top:20px"><summary>Driver installation help</summary><p class="sub">Run Setup.exe or driver/install.ps1 as administrator on Windows to install the StadiaLink driver.</p></details></section><section class="card"><h2>Response time</h2><p class="sub" id="measurement">${measuring?'Measuring demo for 6 seconds…':report?'Demo report ready':'App timings · HID reads and UI sample age'}</p><div class="actions"><button id="measure" ${measuring?'disabled':''} onclick="measure()">Measure for 6 s</button><button onclick="openReport()">Open report</button></div></section><section class="card"><h2>Updates</h2><p class="sub">StadiaLink · local build</p><p class="sub">Local build. No remote updates.</p></section><section class="card"><h2>Files & about</h2><div class="actions"><button onclick="info('Profiles folder','Installed app location: %LOCALAPPDATA%\\StadiaStudio. This preview stores saved profiles in this browser only.')">Open profiles folder</button><a href="brand.html">Icon & logo</a></div><p class="sub">StadiaLink · Controller configuration for Windows</p></section></div>`}
function shortcutSummary(n){const action=draft.Actions[n];if(action<13)return action?actionNames[action]:(destinations.find(x=>x[0]===draft.Map[n])?.[1]||'Unmapped');const key=keyOptions.find(x=>x[0]===draft.Keys[n])?.[1]||'Choose a key';const mods=['Ctrl','Alt','Shift','Win'].filter((_,j)=>draft.Modifiers[n]&(1<<j));return [...mods,key].join(' + ')+' · '+(action===13?'Hold':'Press once')}
function shortcut(n){const key=draft.Keys[n]||({12:120,11:121,10:122}[n]);modal('Configure '+physical[n],`<p>Set this same key combination in your game or Discord.</p>${choose('Shortcut key',keyOptions,key,'') }<div class="checkboxes">${['Ctrl','Alt','Shift','Win'].map((x,j)=>`<label><input id="mod-${j}" type="checkbox" ${draft.Modifiers[n]&(1<<j)?'checked':''}> ${x}</label>`).join('')}</div><p><label><input id="hold" type="checkbox" ${(draft.Actions[n]===13||(!draft.Actions[n]&&n===12))?'checked':''}> Hold key while button is pressed</label></p><p class="sub">Checked: push to talk. Unchecked: send a shortcut once to toggle microphone mute or another action.</p>`,`<button class="primary" onclick="commitShortcut(${n})">Update draft</button>`)}
function commitShortcut(n){draft.Keys[n]=+document.querySelector('#dialog select').value;draft.Actions[n]=$('hold').checked?13:14;draft.Map[n]=0;draft.Modifiers[n]=[0,1,2,3].reduce((a,j)=>a+($('mod-'+j).checked?1<<j:0),0);$('dialog').close();dirty();show(current)}
function newProfile(duplicate){if(profiles.length>=100)return info('Profile limit','Keep up to 100 profiles.');modal(duplicate?'Duplicate profile':'New profile',`<label class="field-label" for="new-name">Name</label><input id="new-name" class="textbox" maxlength="60" value="${duplicate?esc(draft.Name+' copy'):'New profile'}">`,`<button class="primary" onclick="createProfile(${duplicate})">Create</button>`)}
function createProfile(duplicate){try{const p=duplicate?clone(draft):defaultProfile();p.Name=$('new-name').value.trim();validate(p);if(profiles.some(x=>x.Name.toLowerCase()===p.Name.toLowerCase()))throw Error('That name is already used.');profiles.push(p);$('dialog').close();loadProfile(profiles.length-1);persist();tell('Profile created · Save & apply when ready')}catch(e){$('dialog-error').textContent=e.message}}
function deleteProfile(){modal('Delete profile?',`<p>Delete ${esc(profiles[index].Name)} from this preview? Keep at least one profile.</p>`,`<button onclick="removeProfile()">Delete profile</button>`)}
function removeProfile(){if(profiles.length<2)return;if(applied===index)applied=-1;else if(applied>index)applied--;profiles.splice(index,1);$('dialog').close();loadProfile(0);persist();tell('Profile deleted in preview')}
function exportProfile(){try{validate(draft);const url=URL.createObjectURL(new Blob([JSON.stringify(draft,null,2)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download=draft.Name.replace(/[^a-z0-9_-]/gi,'_')+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);tell('Profile JSON exported')}catch(e){info('Cannot export',e.message)}}
function importProfile(){modal('Import profile',`<p>Select a StadiaLink JSON profile or paste its contents. Maximum 64 KiB.</p><input type="file" accept=".json,application/json" aria-label="Choose profile JSON" onchange="readImport(this)"><label class="field-label" for="import-json">Profile JSON</label><textarea id="import-json"></textarea>`,`<button class="primary" onclick="commitImport()">Import</button>`)}
async function readImport(input){const f=input.files[0];if(!f)return;if(f.size>65536){$('dialog-error').textContent='File is too large.';return}$('import-json').value=await f.text()}
function commitImport(){try{const text=$('import-json').value;if(new TextEncoder().encode(text).length>65536)throw Error('File is too large.');if(profiles.length>=100)throw Error('Profile limit reached.');const p=validate(JSON.parse(text));const base=p.Name;let num=2;while(profiles.some(x=>x.Name.toLowerCase()===p.Name.toLowerCase()))p.Name=base.slice(0,54)+' '+num++;profiles.push(p);$('dialog').close();loadProfile(profiles.length-1);persist();tell('Imported · Save & apply when ready')}catch(e){$('dialog-error').textContent=e.message}}
function testMotor(name,continuous=false){clearTimeout(motorTimer);if(!connected()||['Driver update required','Bluetooth unavailable','Send failed'].includes(demoState)){if($('motor-status'))$('motor-status').textContent=stateText()+' · reconnect or retry';return}$('motor-status').textContent=name+' · simulated '+signal+'% signal';if(!continuous)motorTimer=setTimeout(stopMotor,1000)}
function stopMotor(){clearTimeout(motorTimer);if($('motor-status'))$('motor-status').textContent='Stopped · no hardware commands sent'}
function measure(){if(!connected())return info('Connect a controller','Connect a controller before measuring.');measuring=true;show(4);setTimeout(()=>{measuring=false;report='Demo report only. Production reports HID read p95 and UI sample-age p95 in milliseconds, sample counts and intervals. No hardware latency was measured by this preview.';if(current===4)show(4);tell('Demo measurement finished')},6000)}
function openReport(){if(!report)return info('Response report',measuring?'Measurement simulation is in progress.':'No report yet. Run a measurement first.');modal('Response timing report',`<p class="banner">Preview only · no hardware measurements</p><p class="sub">Six-second capture. Timing values are in milliseconds.</p><div class="report-scroll" tabindex="0" role="region" aria-label="Timing distribution table"><table class="report-table"><caption>Application timing distributions</caption><thead><tr><th scope="col">Measurement</th>${['Median','p95','p99','Max','Samples'].map(x=>`<th scope="col">${x}</th>`).join('')}</tr></thead><tbody>${['HID query duration','Query intervals','Latest query to UI frame'].map(x=>`<tr><th scope="row">${x}</th>${Array(5).fill('<td><span aria-label="Not measured">—</span></td>').join('')}</tr>`).join('')}</tbody></table></div><dl class="report-summary">${['Render callbacks / second','HID queries / second','WPF rendering tier'].map(x=>`<div><dt>${x}</dt><dd>Not measured</dd></div>`).join('')}</dl><p class="sub">Queries may return cached input. This report excludes physical actuation, radio transport, game polling and display latency. It cannot establish end-to-end latency.</p>`,'<button class="primary" onclick="$(\'dialog\').close()">Close report</button>')}
function accent(c,b){document.documentElement.style.setProperty('--accent',c);try{localStorage.setItem('stadialink-accent',c)}catch{}document.querySelectorAll('.swatch').forEach(x=>x.setAttribute('aria-pressed',x===b));tell('Accent saved in this browser')}
function live(){for(let j=0;j<2;j++){let r=connected()?raw[j]:0;if(current===1&&(draft.Flags&16))r=connected()?raw[1-j]:0;const out=current===1?triggerOutput(r,draft.TriggerDeadzone):r,percent=Math.floor(out*100/255);if($('value-'+j)){$('value-'+j).textContent=percent+'%';$('meter-'+j).setAttribute('aria-valuenow',percent);$('meter-'+j).setAttribute('aria-valuetext',percent+' percent'+(!connected()?' · controller disconnected':''));$('fill-'+j).style.width=percent+'%';if(current===1){$('raw-'+j).style.left=r*100/255+'%';$('threshold-'+j).style.left=draft.TriggerThreshold+'%';$('dz-'+j).style.width=draft.TriggerDeadzone+'%';$('readout-'+j).textContent='Input '+Math.floor(r*100/255)+'% · Output '+percent+'%'}}if($('motor-output-'+j))$('motor-output-'+j).textContent='Test output: '+Math.floor(Math.min(255,Math.floor(255*signal/100)*draft[j?'WeakScale':'StrongScale']/100)*100/255)+'%';if($('ring-'+j)){let src=draft.Flags&32?1-j:j;const vals=[0,1].map(k=>connected()?axes[src*2+k]:128),dz=draft[j?'RightDeadzone':'LeftDeadzone'],gain=draft[j?'RightSensitivity':'LeftSensitivity'];$('ring-'+j).setAttribute('r',64*dz/100);['cx','cy'].forEach((k,t)=>{$('input-'+j).setAttribute(k,70+(vals[t]-128)/127*64);$('output-'+j).setAttribute(k,70+axisOutput(vals[t],dz,gain,!!(draft.Flags&(1<<(j*2+t))))*64)});$('xy-'+j).textContent='○ Input · ● Output'}}}
function updateConnectionStatus(){const status=document.querySelector('.connected');let tone='success',title='Connected',detail=demoState==='Charging'?'USB · Charging':demoState==='USB'?'USB connection':'Bluetooth connection',symbol='<path d="m7 12 3 3 7-7"/>';if(demoState==='Disconnected'){tone='offline';title='Disconnected';detail='Connect USB or pair Bluetooth';symbol='<path d="m8 8 8 8m0-8-8 8"/>'}else if(demoState==='Driver update required'){tone='warning';title='Driver update needed';detail='Controller detected';symbol='<path d="M12 7v6m0 3h.01"/>'}else if(demoState==='Bluetooth unavailable'){tone='warning';title='Vibration unavailable';detail='Bluetooth channel unavailable';symbol='<path d="M12 7v6m0 3h.01"/>'}else if(demoState==='Send failed'){tone='error';title='Command failed';detail='Controller connected · Retry';symbol='<path d="M12 7v6m0 3h.01"/>'}status.dataset.tone=tone;const markup=`<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="9"/>${symbol}</svg><span><strong>${title}</strong><small>${detail}</small></span>`;if(status.innerHTML!==markup)status.innerHTML=markup;const badge=document.querySelector(".connection");if(badge){badge.dataset.tone=tone;badge.innerHTML=markup}}
function updateBattery(){const unknown=demoState==='USB',charging=demoState==='Charging',battery=document.querySelector('.battery');document.querySelector('.battery-row').hidden=!connected();battery.style.setProperty('--battery-level',unknown?0:batteryPercent);battery.classList.toggle('low',!unknown&&batteryPercent<=15);battery.querySelector('span').textContent=unknown?'?':batteryPercent+'%';battery.setAttribute('aria-label',unknown?'Battery unavailable':`Battery ${batteryPercent} percent${charging?', charging':''}`);document.querySelector('.battery-row p').textContent=unknown?'Battery unavailable':charging?(batteryPercent===100?'Fully charged':'Charging'):batteryPercent<=15?'Low battery':'Battery remaining';if($('battery-output'))$('battery-output').textContent=batteryPercent+'%'}
function changeState(v){demoState=v;document.querySelector('select[aria-label="Demo state"]').value=v;$('device').selectedIndex=['USB','Charging'].includes(v)?1:0;clearTimeout(motorTimer);updateConnectionStatus();updateBattery();$('deviceId').textContent=stateText();show(current)}
function trayPreview(){const known=connected()&&demoState!=='USB',label=connected()?'Battery: '+(known?batteryPercent+'%':'unavailable')+(demoState==='Charging'?(batteryPercent===100?' · Fully charged':' · Charging'):''):'Controller disconnected';modal('System tray preview',`<p class="sub">Notification-area icon and context menu · simulated</p><div class="tray-surface"><div class="tray-popover"><p>${esc(label)}</p><hr><button onclick="$('dialog').close();restore()">Open StadiaLink</button><button onclick="exitTrayPreview()">Exit preview</button></div><div class="tray-taskbar"><span class="sub">Notification area</span><button class="tray-badge ${known&&batteryPercent<=15?'low':''}" aria-label="${esc(label)}. Double-click to open StadiaLink" title="${esc(label)}" ondblclick="$('dialog').close();restore()">${known?`<strong>${batteryPercent}</strong><i style="width:${Math.max(4,batteryPercent)}%"></i>`:'<img src="assets/stadialink-icon-16.svg" width="16" height="16" alt="StadiaLink">'}</button></div></div><p class="sub">The installed app keeps a battery badge in the notification area. Double-clicking it opens StadiaLink. Exit ends the app; minimizing keeps it available.</p>`)}
function exitTrayPreview(){$('dialog').close();minimize();$('restore').textContent='Relaunch StadiaLink preview';tell('Preview exited · saved profiles remain in this browser')}
$('profile').onchange=e=>pickProfile(+e.target.value);$('device').onchange=e=>changeState(e.target.selectedIndex===1?'USB':'Bluetooth');
document.querySelector('.review').insertAdjacentHTML('beforeend','<button onclick="trayPreview()">Tray preview</button>');
document.querySelector('.notice').insertAdjacentHTML('beforebegin',`<details class="demo"><summary>Demo controls · simulated input and connection states</summary><p>No controller is connected to this HTML preview. Use these controls to inspect UI behavior.</p>${choose('Demo state',['Bluetooth','USB','Charging','Disconnected','Driver update required','Bluetooth unavailable','Send failed'],demoState,'changeState(this.value)')}<label class="range-label" for="demo-battery">Battery level <output id="battery-output">42%</output></label><input id="demo-battery" aria-label="Demo battery level" type="range" min="0" max="100" value="42" oninput="batteryPercent=+this.value;updateBattery()"><p class="sub">USB demonstrates an unavailable reading. Charging demonstrates a known reading. Low battery: 15% or less; full charge: 100%.</p><div class="two">${[0,1].map(j=>`<label>${j?'R2':'L2'} raw input<input aria-label="Demo ${j?'R2':'L2'} raw input" type="range" min="0" max="255" value="${raw[j]}" oninput="raw[${j}]=+this.value;live()"></label>`).join('')}${axes.map((v,j)=>`<label>${j<2?'Left':'Right'} ${j%2?'Y':'X'} axis<input type="range" aria-label="Demo axis ${j}" min="0" max="255" value="128" oninput="axes[${j}]=+this.value;live()"></label>`).join('')}</div></details>`);
try{const c=localStorage.getItem('stadialink-accent');if(/^#[0-9a-f]{6}$/i.test(c))document.documentElement.style.setProperty('--accent',c);const saved=JSON.parse(localStorage.getItem('stadialink-profiles-v3'));if(Array.isArray(saved)&&saved.length&&saved.length<=100){profiles=saved.map(validate);draft=clone(profiles[0])}}catch{}
updateConnectionStatus();
updateBattery();
show(0);
